RefreshProjectsButton.OnSelect:
Set(varProjectsLoading, true); Set(varProjectCatalogError, ""); Set(varCatalogLoaded, false);
ClearCollect(colProjects, {Value: "Select a project", ProjectId: ""});
IfError(
    Set(varProjectCatalogResponse, ACORNSharePointPilotCatalog.Run());
    With({catalog: ParseJSON(varProjectCatalogResponse.catalogjson)},
        If(!IsBlank(Text(catalog.error)) || Text(catalog.source) <> "sharepoint",
            Set(varProjectCatalogError, "The project list is unavailable. Contact the app owner."),
            Collect(colProjects, ForAll(Table(catalog.projects), {Value: Text(ThisRecord.Value.label), ProjectId: Text(ThisRecord.Value.id)}));
            Set(varCatalogLoaded, true))),
    ClearCollect(colProjects, {Value: "Select a project", ProjectId: ""});
    Set(varProjectCatalogError, "Projects could not be loaded. Please try Refresh Project List."));
Set(varProjectsLoading, false); Reset(ProjectDropdown)

SubmitButton.OnSelect:
If(!varSubmitting && varDisposition <> "exported" && varDisposition <> "conflict",
    Set(varSubmitting, true);
    Set(varSubmissionStatus, "Saving your highlight…");
    Set(varCanSend, false);
    If(IsBlank(varPendingJson),
        IfError(
            With({newId: Lower(Text(GUID())), newAt: Text(Now(), DateTimeFormat.UTC)},
                With({payload: JSON({entry: {archived: false, category: CategoryDropdown.Selected.Value, eventType: If(EventTypeDropdown.Selected.Value = "Not specified", Blank(), EventTypeDropdown.Selected.Value), global: PlacementDropdown.Selected.Value = "General update (report title page)", items: If(IsEmpty(Filter(Split(Substitute(ItemsInput.Text, Char(13), ""), Char(10)), !IsBlank(Trim(Value)))), Blank(), ForAll(Filter(Split(Substitute(ItemsInput.Text, Char(13), ""), Char(10)), !IsBlank(Trim(Value))), Trim(Value))), origin: "manual", state: StateDropdown.Selected.Value, summary: Trim(SummaryInput.Text), timestamp: Text(OccurredOnPicker.SelectedDate, DateTimeFormat.UTC)}, projectId: ProjectDropdown.Selected.ProjectId, submissionId: newId, submittedAt: newAt, submitter: {email: Lower(User().Email)}}, JSONFormat.Compact & JSONFormat.FlattenValueTables)},
                    Set(varPendingJson, payload); Set(varPendingId, newId); Set(varPendingProjectLabel, ProjectDropdown.Selected.Value); Set(varDisposition, "pending"); Set(varCanSend, true))),
            Set(varSubmissionStatus, "We couldn't prepare your highlight. Your entries are still here. Please try again.")),
        Set(varCanSend, true)
    );
    If(varCanSend,
        ClearCollect(colPendingHighlight, {payload: varPendingJson, owner: Lower(User().Email), projectLabel: varPendingProjectLabel, disposition: "pending", exportFileUrl: "", receiptUrl: ""});
        IfError(SaveData(colPendingHighlight, "SponsorHighlightSharePointPending"); true,
            Set(varCanSend, false); Set(varSubmissionStatus, "Browser recovery is unavailable. Nothing was sent. Open the published app in a regular browser window and try again."))
    );
    If(varCanSend,
        Set(varDisposition, "pending");
        IfError(
            With({receipt: ACORNSharePointPilotIntake.Run(varPendingJson)},
                If(receipt.submissionid = varPendingId && receipt.status = "received",
                    Set(varReceiptUrl, receipt.receipturl);
                    Set(varExportFileUrl, If(receipt.exportstatus = "exported" && receipt.exportfileurl = "https://ornl.sharepoint.com/sites/ResearchEnablement/Sponsor%20Highlights%20JSONL%20Pilot/" & varPendingId & ".jsonl", receipt.exportfileurl, ""));
                    Set(varDisposition, If(!IsBlank(varExportFileUrl), "exported", "received"));
                    Set(varSubmissionStatus, If(varDisposition = "exported", "Highlight received in SharePoint. Its JSONL export is verified and ready for ACORN review. This does not publish a report.", "Highlight received in SharePoint. The JSONL export is not yet confirmed. Select Retry JSONL export to finish safely with the same receipt ID."));
                    ClearCollect(colPendingHighlight, {payload: varPendingJson, owner: Lower(User().Email), projectLabel: varPendingProjectLabel, disposition: varDisposition, exportFileUrl: varExportFileUrl, receiptUrl: varReceiptUrl});
                    IfError(SaveData(colPendingHighlight, "SponsorHighlightSharePointPending"); true, Set(varSubmissionStatus, varSubmissionStatus & " Browser recovery could not store the updated receipt; a retry will safely confirm the same submission.")),
                    receipt.submissionid = varPendingId && receipt.status = "rejected",
                    Set(varDisposition, "rejected"); Set(varSubmissionStatus, "Not submitted. The highlight did not pass validation. Select Edit highlight to correct it, or contact the app owner."),
                    receipt.submissionid = varPendingId && receipt.status = "conflict",
                    Set(varDisposition, "conflict"); Set(varSubmissionStatus, "This receipt ID has different content in SharePoint. Keep this page and contact the app owner with the receipt ID below."),
                    Set(varDisposition, "pending"); Set(varSubmissionStatus, "We could not confirm the save. Your pending highlight is retained in this browser. Select Retry submission; the same ID prevents a duplicate."))),
            Set(varDisposition, "pending"); Set(varSubmissionStatus, "We could not confirm the save. Your pending highlight is retained in this browser. Select Retry submission; the same ID prevents a duplicate."))
    );
    Set(varSubmitting, false);
    Set(varShowSubmissionResult, true)
)

RestoreDraftButton.OnSelect:
If(!Coalesce(varRecoveryLoaded, false),
    Set(varRecoveryBlocked, false);
    ClearCollect(colPendingHighlight, {payload: "", owner: "", projectLabel: "", disposition: "", exportFileUrl: "", receiptUrl: ""}); Clear(colPendingHighlight);
    IfError(
        LoadData(colPendingHighlight, "SponsorHighlightSharePointPending", true);
        If(!IsEmpty(colPendingHighlight),
            If(CountRows(colPendingHighlight) <> 1 || First(colPendingHighlight).owner <> Lower(User().Email),
                Set(varRecoveryBlocked, true); Set(varSubmissionStatus, "This browser has a pending highlight for another account. Sign in with that account to resolve it before submitting here."),
                With({saved: First(colPendingHighlight)},
                    With({draft: ParseJSON(saved.payload)},
                        If(Text(draft.submitter.email) <> Lower(User().Email) || !IsMatch(Text(draft.submissionId), "[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"),
                            Set(varRecoveryBlocked, true); Set(varSubmissionStatus, "The saved highlight could not be verified. Contact the app owner before sending another highlight."),
                            Set(varPendingJson, saved.payload); Set(varPendingId, Text(draft.submissionId)); Set(varPendingProjectLabel, saved.projectLabel); Set(varRestoredDraft, draft);
                            Set(varExportFileUrl, saved.exportFileUrl); Set(varReceiptUrl, saved.receiptUrl); Set(varDisposition, If(saved.disposition = "exported" && saved.exportFileUrl = "https://ornl.sharepoint.com/sites/ResearchEnablement/Sponsor%20Highlights%20JSONL%20Pilot/" & varPendingId & ".jsonl", "exported", saved.disposition = "received", "received", "pending"));
                            ClearCollect(colProjects, {Value: saved.projectLabel, ProjectId: Text(draft.projectId)});
                            Set(varSubmissionStatus, If(varDisposition = "exported", "Highlight received in SharePoint. Its JSONL export is verified and ready for ACORN review.", varDisposition = "received", "Highlight received in SharePoint. Select Retry JSONL export to confirm its export.", "Pending highlight recovered. Select Retry submission to confirm its save without creating a duplicate."));
                            Reset(ProjectDropdown); Reset(OccurredOnPicker); Reset(CategoryDropdown); Reset(StateDropdown); Reset(EventTypeDropdown); Reset(SummaryInput); Reset(ItemsInput); Reset(PlacementDropdown)
                        )
                    )
                )
            )
        ); Set(varRecoveryLoaded, true),
        Set(varRecoveryBlocked, true); Set(varSubmissionStatus, "Browser recovery is unavailable. Open the published app in a regular browser window. Your pending data has not been cleared.")
    );
    Set(varShowSubmissionResult, varRecoveryBlocked || !IsBlank(varPendingJson));
    If(IsBlank(varPendingJson) && !varRecoveryBlocked && !Coalesce(varCatalogLoaded, false), Select(RefreshProjectsButton))
)

EditDraftButton.OnSelect:
If(!varSubmitting && varDisposition in ["exported", "rejected"],
    IfError(ClearData("SponsorHighlightSharePointPending"),
        Set(varSubmissionStatus, "The saved browser record could not be cleared. Please try again before starting another highlight."); Set(varShowSubmissionResult, true),
        If(varDisposition = "exported", Set(varRestoredDraft, Blank()), Set(varRestoredDraft, ParseJSON(varPendingJson))); Set(varPendingProjectLabel, Blank());
        Clear(colPendingHighlight); Set(varPendingJson, Blank()); Set(varPendingId, Blank()); Set(varExportFileUrl, Blank()); Set(varReceiptUrl, Blank()); Set(varDisposition, Blank()); Set(varSubmissionStatus, Blank());
        Reset(OccurredOnPicker); Reset(CategoryDropdown); Reset(StateDropdown); Reset(EventTypeDropdown); Reset(SummaryInput); Reset(ItemsInput); Reset(PlacementDropdown);
        Select(RefreshProjectsButton); Set(varShowSubmissionResult, false)
    )
)
